func strictJSONFileIn(files Files, path string, target any) error {
	file, err := files.Open(path)
	if err != nil {
		return err
	}
	defer file.Close()
	raw, err := io.ReadAll(io.LimitReader(file, maxReviewBundleBytes+1))
	if err != nil {
		return err
	}
	if len(raw) > maxReviewBundleBytes {
		return fmt.Errorf("review artifact exceeds %d bytes", maxReviewBundleBytes)
	}
	if err := rejectDuplicateJSONKeysAndControls(raw); err != nil {
		return err
	}
	decoder := json.NewDecoder(bytes.NewReader(raw))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(target); err != nil {
		return err
	}
	var trailing any
	if err := decoder.Decode(&trailing); err != io.EOF {
		if err == nil {
			return fmt.Errorf("trailing JSON content")
		}
		return fmt.Errorf("trailing JSON content: %w", err)
	}
	return nil
}

